style.css:
/* Set the background */
html, body {
  background-color: #ffb6c1; /* Light pink background */
  background-image: url("https://i.imgur.com/RUtQGpg.jpeg");
  background-repeat: no-repeat;
  background-position: center center;
  background-attachment: fixed;
  background-size: cover;
  color: #ff69b4;
  margin: 0;
  padding: 0;
}

/* Apply styles to all text elements */
*, a, span, div, p, strong, button {
  color: #ff69b4;
}

/* Style headers if they're present */
h1, h2, h3, h4, h5, h6 {
  color: #ff69b4;
}

/* Soft pink text highlight */
::selection {
  background: #ffd1e7;
  color: white;
}
